-- SALY-only employer loan legal foundation. No legal clearance or C2 close; preserve tax results.
BEGIN;
DO $gate$ BEGIN
 IF (SELECT count(*) FROM saly.programas_investigacion p JOIN saly.proyecto pr ON pr.id=p.proyecto_id
 WHERE p.codigo='SALY_FONDEO_LEGAL' AND pr.codigo='SALY-001')<>1 THEN RAISE EXCEPTION 'WRONG_SALY_PROJECT'; END IF;
 IF (SELECT count(*) FROM saly.checkpoints_investigacion c JOIN saly.unidades_investigacion u ON c.unidad_id=u.id
 WHERE u.codigo='SALY-LEG-05' AND c.codigo='C2' AND c.estado='EN_CURSO' AND c.dictamen_revision IS NULL)<>1 THEN
 RAISE EXCEPTION 'WRONG_LEG05_C2_STATE'; END IF;
 IF EXISTS(SELECT 1 FROM saly.evidencias WHERE codigo='SALY-EVD-LEG-05-C2-BASE-JURIDICA-20261021') THEN RAISE EXCEPTION 'EVIDENCE_EXISTS'; END IF;
 IF (SELECT count(*) FROM saly.escenarios WHERE codigo IN('SALY-ESC-011','SALY-ESC-012','SALY-ESC-013','SALY-ESC-014')
 AND estado='BORRADOR' AND (parametros->'evaluacion_legal'->>'dictamen_final') IS NULL
 AND NOT ((parametros->'evaluacion_legal') ? 'fundamento_juridico_prestamo_patronal'))<>4 THEN RAISE EXCEPTION 'SCENARIO_PRECONDITION'; END IF;
END $gate$;
INSERT INTO saly.evidencias(codigo,tipo,titulo,descripcion,referencia,fecha_evidencia,hechos,estado)
VALUES('SALY-EVD-LEG-05-C2-BASE-JURIDICA-20261021','ANALISIS_APLICADO_NORMAS_CASOS',
 'Base jurídica de préstamos de empleador a trabajador: ENAPU 2026, CTS, Código Civil y empresa eléctrica',
 'Cadena jurídica de mutuo sin intereses, crédito laboral y garantía CTS, tratamiento LIR y casos ENAPU y Electro Sur Este. Separa normativa general de reglamentación FONAFE exclusiva estatal; SBS 650-2024 requiere análisis separado. SALY como SaaS sin préstamo propio en ruta A. No habilitación final.',
 'Documentos públicos oficiales ENAPU 2026 y 2024, Electro Sur Este 2013; CC1648/1663; CTS40/47; SUNAT art26; SBS 00027-2024-SAAJ.',
 DATE '2026-10-21','{"schema":"saly.legal_employer_loan_foundation/v1","program":"SALY_FONDEO_LEGAL","fecha":"2026-10-21","country":"PERU","phase":"C2_DOCUMENTED_FINDINGS_NO_LEGAL_CLEARANCE","checkpoint":"SALY-LEG-05/C2","legal_authorization":false,"registrability_sbs_exception_proved":false,"source_public_primary":true,"findings":[{"norm":"Código Civil, DL 295, arts. 1648 y 1663","source":"https://diariooficial.elperuano.pe/Normas/obtenerDocumento?idNorma=60","rule":"Mutuo de dinero: devolución de importe prestado. Art. 1663 permite pacto distinto a intereses, incluida gratuidad civil; NO suprime presunción tributaria si corresponde.","status":"BASE_CIVIL_GENERAL"},{"norm":"TUO Ley de CTS DS001-97-TR arts.40 y 47","source":"https://www2.congreso.gob.pe/sicr/cendocbib/con4_uibd.nsf/9FA02BD0B2DE872705257E2200539E31/%24FILE/3_DECRETO_SUPREMO_001_26_1_1996.pdf","rule":"La propia norma reconoce créditos de trabajadores frente al empleador por préstamos y adelantos. Permite garantías CTS hasta 50% conjunto, comunicación a depositario y mecanismo de cese art47, condicionado a formalidades y leyes vigentes.","status":"BASE_LABORAL_DIRECTA_CON_LIMITES"},{"norm":"TUO Ley Impuesto Renta DS179-2004-EF art.26","source":"https://www.sunat.gob.pe/legislacion/renta/ley/capv.pdf","rule":"Excepciones a intereses presuntos para adelantos de sueldo del personal no mayores a 1 UIT, determinados préstamos vivienda y préstamos empleador-trabajador en convenio colectivo debidamente aprobado; otros mutuos siguen reglas generales de presunción.","status":"EXCEPCION_TRIBUTARIA_NO_AUTORIZACION_FINANCIERA"},{"norm":"TUO Relaciones Colectivas de Trabajo DS010-2003-TR art.42","source":"https://lpderecho.pe/texto-unico-ordenado-ley-relaciones-colectivas-trabajo-decreto-supremo-010-2003-tr-actualizado/","rule":"Fuerza vinculante de convenios colectivos dentro de su ámbito; no es obligatorio convenio colectivo para todo mutuo individual, pero puede fundamentar beneficios laborales determinados.","status":"BASE_COLECTIVA_SEGUN_CASO"},{"norm":"Ley General Sociedades 26887 art.11","source":"https://www2.congreso.gob.pe/sicr/cendocbib/con4_uibd.nsf/F192BA67C92F4D5C0525804900719FA2/%24FILE/pe061es.pdf","rule":"Actos que favorecen fines de sociedad y se vinculan a objeto social, sin ejercer actividades reservadas por ley; comprobar estatuto/poderes/órganos de cada empleador privado.","status":"BASE_SOCIETARIA_REQUIERE_ESTADISTICA_ESTATO"},{"norm":"SBS Res. 650-2024 y Informe N. 00027-2024-SAAJ","source":"https://www.sbs.gob.pe/Portals/0/INFORME%20N%2000027-2024-SAAJ.pdf","rule":"Empresas dedicadas a prestar con fondos propios requieren registro SBS/UIF, el registro no confiere validez civil a contratos; no hallada exención expresa para programa exclusivo a empleados.","status":"LIMITACION_NO_DESPEJADA"}],"employers":[{"name":"ENAPU","type":"ESTATAL_PORTUARIA","source":"https://www.enapu.com.pe/sistema-transparencia/views/documentos/5142125139politica%20de%20otorgamiento%20de%20prestamos%20al%20personal%20de%20la%20eanpu%20s.a..pdf","document":"PL-POP-ENAPU-001-2026 aprobada 30 enero 2026","base_cited":["Código Civil","DL 1693 empresa estatal FONAFE","DS 292-2024-EF","TUO DL728","Relaciones colectivas","TUO Impuesto Renta","Directivas empresariales y acuerdo directorio"],"evidence":"Declaración expresamente: préstamos a personal aunque actividades principal y complementarias no sean financiación; evaluar casos, costos, fondos. Préstamo escolar S/4500, 10 meses: condición interna, NO tope general.","transfer_to_saly":"Código Civil, LIR, análisis laboral y aprobación corporativa; NO transferir DL1693/DS292-2024 ni directivas FONAFE a empresa privada."},{"name":"ENAPU","type":"ESTATAL_PORTUARIA","source":"https://www.enapu.com.pe/sistema-transparencia/views/documentos/5791988186ad%20009%2002%202024.pdf","document":"Acuerdo Directorio 009/02/2024/D","evidence":"Refiere Informe Legal 014-2024-ENAPU/OAJ con conclusión limitada a facultad del Directorio para aprobar política; desde 2007 préstamos escolaridad sin interés vía convenio pago, CC1663. Informe completo NO recuperado.","transfer_to_saly":"Acta de órgano competente más informe legal específico del empleador; no prueba exención SBS."},{"name":"ELECTRO SUR ESTE SAA","type":"ESTATAL_ELECTRICA","source":"https://www.else.com.pe/ArchivosTransparencia/1001000392.pdf","document":"Directiva G-002-2013 Normas para el otorgamiento de préstamos al personal","evidence":"Base legal expresa convenio colectivo 29-11-2012 y convenios bancarios; distingue préstamo de la empresa y descuento de terceros; capacidad de pago y control. Saldo S/500 es norma interna de 2013, NO límite legal universal.","transfer_to_saly":"Política RRHH y reglas de control de endeudamiento; sustento colectivo cuando aplique; evitar copiar montos/porcentajes sin derecho vigente."}],"saly_application":{"priority_model":"SALY-ESC-011","legal_construction":"Empleador privado origina mutuo trabajador desde fondos propios, fija precio/interés o gratuidad por pacto, asume acreencia, descuento planilla dentro de límites, SALY solo arrendamiento tecnología/servicio; NO cesión de cartera.","required_papers":["Estatuto/poderes del empleador, aprobación de política de préstamos y presupuesto","Contrato de préstamo empleador/trabajador por transacción, términos y pacto sobre intereses","Autorización de descuento con reglas de protección salarial y órdenes judiciales","Contrato SALY SaaS + tratamiento de datos personales, sin titularidad ni custodia de dinero salvo marco apropiado","Informe del abogado/criterio SBS sobre actividad incidental versus empresas dedicadas y obligaciones UIF","Condiciones CTS art40, documentos de garantía y su comunicación al depositario cuando proceda"],"labor_question":"El TC aplica protección de remuneración frente a descuentos acordados. Garantía CTS y cobro al cese no permiten descontar por cualquier concepto de forma indiscriminada.","regulatory_question":"Código Civil y CTS prueban validez abstracta del préstamo laboral; NO son pronunciamiento que excluya clasificación SBS 650-2024 para producto masivo mensual mediante SaaS.","legal_risk_model_variants":{"A":"Mutuo empleador-trabajador; artículos CC y CTS son directamente relevantes sujeto a condiciones.","B":"Igual que A si empleador sigue siendo realmente acreedor; estudiar mandato y titularidad de cuentas.","C":"Crédito nace en SALY y se cede al empleador: CC cesión; no presumir que todas prerrogativas de crédito concedido originalmente por empleador se transmiten sin revisar.","D":"Mutuo empleador-SALY y SALY-trabajador: no es préstamo del empleador a trabajador, por lo que fundamentación específica CTS y LIR empleados no se aplica automáticamente."},"next":"C2 empleador piloto, contratos, análisis SBS del término dedicada, ahorro cumplimiento, riesgos laborales; C3 revisión independiente. Sin aprobación."},"caveats":["El documento ENAPU 2026 cita versión 010-2010-TR de TUO relaciones colectivas; contraste jurídico oficial indica DS010-2003-TR. Verificar cita antes de reproducir plantillas.","Convenio colectivo de empresa estatal y prerrogativas FONAFE no aplican automáticamente al empleador privado.","Artículo CTS 40 vigente y leyes de disponibilidad CTS deben revisarse caso por caso; no equivale a disponibilidad irrestricta."],"status":"NO_CONCLUIDO_APTO"}'::jsonb,'VIGENTE');
INSERT INTO saly.checkpoint_evidencias(checkpoint_id,evidencia_id,tipo_relacion)
SELECT c.id,e.id,'FUNDAMENTO_JURIDICO_C2_SIN_CIERRE'
FROM saly.checkpoints_investigacion c JOIN saly.unidades_investigacion u ON u.id=c.unidad_id
JOIN saly.evidencias e ON e.codigo='SALY-EVD-LEG-05-C2-BASE-JURIDICA-20261021'
WHERE u.codigo='SALY-LEG-05' AND c.codigo='C2';

UPDATE saly.escenarios s SET
 parametros=jsonb_set(s.parametros,'{evaluacion_legal,fundamento_juridico_prestamo_patronal}',r.payload,true),
 updated_at=now()
FROM (VALUES
('SALY-ESC-011','{"code":"SALY-ESC-011","scope":"APLICACION_DIRECTA","legal_route":"Mutuo empleador-trabajador, CC1648/1663; CTS40/47; LIR26 según supuestos; proveedor SaaS SALY.","conditions":["Empleador acreedor real","Solo fondos propios","Decisión crediticia y política interna del empleador","SBS no categorizado aún","Límites laborales y fiscales"],"evidence":"SALY-EVD-LEG-05-C2-BASE-JURIDICA-20261021","formal_legal_clearance":false,"phase":"C2_NO_FINAL"}'::jsonb),
('SALY-ESC-012','{"code":"SALY-ESC-012","scope":"APLICACION_DIRECTA_CON_MANDATO","legal_route":"Mutuo del empleador al trabajador administrado por SALY bajo mandato; requiere revisar custodia y facultades.","conditions":["Titularidad empresario","Segregación de caja","Licencia para manejo de fondos si relevante","SBS del empleador y laborales pendientes"],"evidence":"SALY-EVD-LEG-05-C2-BASE-JURIDICA-20261021","formal_legal_clearance":false,"phase":"C2_NO_FINAL"}'::jsonb),
('SALY-ESC-013','{"code":"SALY-ESC-013","scope":"APLICACION_LIMITADA_CESION","legal_route":"SALY originador y cesión contemporánea; no es idéntico al crédito concedido por empleador para beneficios CTS y tributarios.","conditions":["Cesión escrita oponible","Revisión estatus acreedor a efectos CTS40/47","SBS de originador/cesionario según realidad"],"evidence":"SALY-EVD-LEG-05-C2-BASE-JURIDICA-20261021","formal_legal_clearance":false,"phase":"C2_NO_FINAL"}'::jsonb),
('SALY-ESC-014','{"code":"SALY-ESC-014","scope":"NO_APLICACION_AUTOMATICA","legal_route":"Préstamo de empresa a SALY y préstamo de SALY a empleado: dos mutuos; las excepciones de préstamo patronal no se presumen.","conditions":["Mutuo B2B","Registro/intereses entre empresas","Contrato y cumplimiento SALY trabajador","SBS ambos actores según realidad"],"evidence":"SALY-EVD-LEG-05-C2-BASE-JURIDICA-20261021","formal_legal_clearance":false,"phase":"C2_NO_FINAL"}'::jsonb)
) AS r(codigo,payload)
WHERE s.codigo=r.codigo AND s.estado='BORRADOR' AND s.parametros->>'familia'='MODELOS_FONDEO_TRIBUTOS';
DO $v$ BEGIN
 IF (SELECT count(*) FROM saly.escenarios s
 WHERE s.codigo IN ('SALY-ESC-011','SALY-ESC-012','SALY-ESC-013','SALY-ESC-014')
 AND s.parametros->'evaluacion_legal'->'fundamento_juridico_prestamo_patronal'->>'formal_legal_clearance'='false'
 AND s.parametros->'evaluacion_legal'->>'dictamen_final' IS NULL
 AND s.parametros->'validacion'->>'legal'='PENDIENTE') <> 4 THEN RAISE EXCEPTION 'SCENARIO_READBACK_FAIL'; END IF;
 IF (SELECT count(*) FROM saly.checkpoint_evidencias ce JOIN saly.evidencias e ON e.id=ce.evidencia_id
 WHERE e.codigo='SALY-EVD-LEG-05-C2-BASE-JURIDICA-20261021')<>1 THEN RAISE EXCEPTION 'EVIDENCE_LINK_FAIL'; END IF;
 IF (SELECT count(*) FROM saly.checkpoints_investigacion c JOIN saly.unidades_investigacion u ON c.unidad_id=u.id
 JOIN saly.programas_investigacion p ON p.id=u.programa_id
 WHERE p.codigo='SALY_FONDEO_LEGAL' AND c.estado='DONE')<>5 THEN RAISE EXCEPTION 'DONE_DRIFT_FAIL'; END IF;
 IF (SELECT count(*) FROM saly.checkpoints_investigacion c JOIN saly.unidades_investigacion u ON u.id=c.unidad_id
 WHERE u.codigo='SALY-LEG-05' AND c.codigo='C2' AND c.estado='EN_CURSO')<>1 THEN RAISE EXCEPTION 'C2_PROMOTION_FAIL'; END IF;
END $v$;
COMMIT;